package com.bank.payments.adapters.out.jdbc;

import com.bank.payments.domain.model.Account;
import com.bank.payments.domain.port.AccountRepository;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

import java.util.List;
import java.util.Optional;

/** JDBC adapter of the port AccountRepository (table account, legacy db_cuentas..ct_cuenta). */
@Repository
public class JdbcAccountRepository implements AccountRepository {

    private final JdbcTemplate jdbcTemplate;

    public JdbcAccountRepository(JdbcTemplate jdbcTemplate) {
        this.jdbcTemplate = jdbcTemplate;
    }

    @Override
    public Optional<Account> findByNumberAndType(String accountNumber, String accountType) {
        List<Account> rows = jdbcTemplate.query(
                "SELECT account_number, account_type, balance FROM account "
                        + "WHERE account_number = ? AND account_type = ?",
                (rs, rowNum) -> new Account(
                        rs.getString("account_number"),
                        rs.getString("account_type"),
                        rs.getBigDecimal("balance")),
                accountNumber, accountType);
        return rows.stream().findFirst();
    }
}

